sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float2 center;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float s = clamp(amount, 0.0, 1.9);
    half4 sum = half4(0);
    for (int i = 0; i < 48; ++i) {
        sum += image.eval(c + d * (1.0 + s * (float(i) / 47.0 - 0.5)));
    }
    return sum / 48.0;
}
